def transform(grid):
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    candidates = [i for i, row in enumerate(grid) if len(set(row)) == 1]
    sep = min(candidates, key=lambda i: counts[grid[i][0]])
    top, bottom = grid[:sep], grid[sep+1:]
    common = set(v for r in top for v in r) & set(v for r in bottom for v in r)
    base = min(common, key=lambda v: sum(r.count(v) for r in top + bottom))
    return [[3 if a == base and b == base else base for a, b in zip(x, y)] for x, y in zip(top, bottom)]
